contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address receiver, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(receiver != address(0));
        // Ensure this test contract has enough balance to potentially cover pre-funded operations (if needed by external test harness)
        require(address(this).balance >= 0);

        // Record balances before
        uint beforeC = address(c).balance;
        uint beforeR = receiver.balance;

        // Try calling sendTo and capture whether it reverted
        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Record balances after
        uint afterC = address(c).balance;
        uint afterR = receiver.balance;

        // General rule:
        // - If call succeeded (did not revert) then C's balance decreased by amount and receiver's balance increased by amount.
        // - If call reverted then neither balance changed.
        assert(
            (!reverted && beforeC >= amount && afterC + amount == beforeC && afterR == beforeR + amount)
            || (reverted && afterC == beforeC && afterR == beforeR)
        );
    }

    receive() external payable { }
}

